input.newString:
    render(<App />);
    act(() => bump());
    act(() => bump());
    expect(refIdentities.size).toBe(1);
  });

  it('behaves as before when no forwardedRef is passed: the child keeps its own ref by identity', () => {
    // Guard: without a `ref` on `Slot`, the slotted child must still receive its *own*
    // ref function (same identity), not a composed wrapper. A wrapper would be a
    // different function even though calling the child's ref would look the same.
    const observedRefs: React.Ref<HTMLButtonElement>[] = [];
    const childRef = vi.fn();

    const Child = ({ ref, ...props }: React.ComponentPropsWithRef<'button'>) => {
      observedRefs.push(ref);
      return <button {...props} ref={ref} />;
    };

    render(
      <Slot>
        <Child ref={childRef}>hi</Child>
      </Slot>,
    );

    const button = document.querySelector('button')!;
    expect(observedRefs.length).toBe(1);
    expect(observedRefs[0]).toBe(childRef); // not wrapped by a composed ref
    expect(childRef).toHaveBeenCalledWith(button);
  });
});

